package com.digitalhealth.controller;
import com.digitalhealth.dto.MedicalReportDTO; import com.digitalhealth.security.AccessService; import com.digitalhealth.service.MedicalReportService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/workers/{workerId}/reports") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class MedicalReportController {private final MedicalReportService service;private final AccessService access;public MedicalReportController(MedicalReportService s,AccessService a){service=s;access=a;}@GetMapping public List<MedicalReportDTO> list(@PathVariable Long workerId){access.clinicalAccess(workerId);return service.list(workerId);}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) public MedicalReportDTO upload(@PathVariable Long workerId,@RequestParam String title,@RequestParam String reportType,@RequestParam LocalDate reportDate,@RequestParam(required=false) String healthcareCenter,@RequestParam(required=false) String description,@RequestParam MultipartFile file){access.providerOrAdmin();access.clinicalAccess(workerId);return service.upload(workerId,title,reportType,reportDate,healthcareCenter,description,file);}@GetMapping("/{id}/download") public ResponseEntity<byte[]> download(@PathVariable Long workerId,@PathVariable Long id){access.clinicalAccess(workerId);var f=service.file(workerId,id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(f.report().getContentType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+f.report().getOriginalName().replace("\"","")+"\"").body(f.bytes());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long workerId,@PathVariable Long id){access.providerOrAdmin();access.clinicalAccess(workerId);service.delete(workerId,id);}}
